    def get_sw_release_via_targetbd(self, lmp_ip="192.168.255.129", username="toor4nsn", password="oZPS0POrRieRtu"):
        def __get_sw_release():
            self.ssh_conn = ssh.connect(lmp_ip, username, password)
            target_bd = self.ssh_conn.execute(command="ls -1 /ffs/run/TargetBD*.xml", timeout=15)
            sw_pattern = re.compile(r".*TargetBD_(?P<sw>.*)\.xml")
            match = sw_pattern.search(target_bd)
            if match:
                release = match.group("sw").partition("_")[0]
                logging.debug(f"Determined SW release for admin connection: {release}")
                return release if release else None
            else:
                return None
        try:
            self.ssh_con = None
            return __get_sw_release()
        except (ConnectFailedError, CommandExecutionError) as e:
            logging.debug(f"Could not get TargetBD via SSH from {lmp_ip} ({e}). Trying again")
            try:
                return __get_sw_release()
            except (ConnectFailedError, CommandExecutionError) as e:
                logging.error(f"Could not get TargetBD via SSH from {lmp_ip} on second attempt either ({e}). Using"
                              f"default release")
                return None
        finally:
            if self.ssh_con:
                self.ssh_con.disconnect()

    def collect_bts_information(self, info_type, mrbts_info=False):
        return_info = ""
        release = self.get_sw_release_via_targetbd()
        connection = self.admin.connect_to(name='marvin', release=release)
        try:
            if mrbts_info:
                bts_info = connection.get_mrbts_info(detailed_output=True)
                return_info = bts_info.get(info_type, "")
            else:
                bts_info = connection.get_parameters_for_all("BTS")
                return_info = bts_info[0][info_type]
        except IndexError as e:
            logging.debug(f"{info_type} not found\n{''.join(format_exception(type(e), e, e.__traceback__))}")
            return ""
        finally:
            self.admin.teardown_admin(connection='marvin')
            return return_info

    def check_rat(self, also_wcdma=False, also_gsm=False):
        rat_list = []
        release = self.get_sw_release_via_targetbd()
        connection = self.admin.connect_to(name='marvin', release=release)
        try:
            if connection.get_cells_info("nr", timeout=30):
                rat_list.append("5G")
            if connection.get_cells_info("lte", timeout=30):
                rat_list.append("4G")
            if also_wcdma and connection.get_cells_info("wn", timeout=30):
                rat_list.append("3G")
            if also_gsm and connection.get_cells_info("gn", timeout=30):
                rat_list.append("2G")
        except Exception as e:
            logging.error(f"Error: {e} when trying to get RAT"
                          f"\n{''.join(format_exception(type(e), e, e.__traceback__))}")
            return []
        finally:
            self.admin.teardown_admin(connection='marvin')
            return rat_list

    @staticmethod
    def _prepare_environment(env):
        """Prepare environment variables for command execution."""
        if env is True:
            logging.debug("Using current environment variables for command execution")
            env = os.environ.copy()
            http_proxy = os.environ.get("https_proxy", "")
            logging.debug(f"Using https_proxy: {http_proxy}")
        return env

    @staticmethod
    def _execute_command(cmd, env, no_std_messages, timeout=60):
        """Execute a command with or without output messages."""
        if no_std_messages:
            run(
                cmd,
                shell=True,
                env=env,
                stdin=DEVNULL,
                stdout=DEVNULL,
                stderr=DEVNULL,
                check=True,
                timeout=timeout
            )
            return b""
        else:
            return check_output(cmd, shell=True, env=env, timeout=timeout)

    @staticmethod
    def _handle_command_error(e, cmd, suppress_errors, last_exception):
        """Handle command execution errors."""
        if suppress_errors:
            logging.debug(f"Command '{cmd}' returned non-zero exit status {e.returncode}")
            return True  # Signal to break retry loop
        else:
            if last_exception is None:  # Just one exception is logged
                logging.error(f"Error: {e} when trying to send command: {cmd}\n"
                            f"{''.join(format_exception(type(e), e, e.__traceback__))}\n"
                            f"Output: {e.output}")
            else:
                logging.debug("Retrying the command didn't help")
            return False  # Signal to continue retry loop

    def check_output_with_retries(self, cmd, decode=False, env=None, no_std_messages=False, suppress_errors=False,
                                  timeout=60):
        env = self._prepare_environment(env)
        logging.debug(f"Sending command {cmd}")
        last_exception = None
        for i in range(3):
            try:
                output = self._execute_command(cmd, env, no_std_messages, timeout=timeout)
                return output.decode().strip() if decode else output
            except (CalledProcessError, TimeoutExpired) as e:
                last_exception = e
                should_break = self._handle_command_error(e, cmd, suppress_errors, last_exception)
                if should_break:
                    break
            if i < 2:
                sleep(5)
        if last_exception is not None and not suppress_errors:
            raise last_exception
        return None

    @staticmethod
    def check_verdict(verdict):
        if isinstance(verdict, bool):
            if verdict:
                return "Passed"
            else:
                return "Failed"
        elif isinstance(verdict, str):
            if "pass" in verdict.lower():
                return "Passed"
            elif "fail" in verdict.lower():
                return "Failed"
            return None
        else:
            logging.debug(f"Verdict {verdict} is not valid. Use 'Passed' or 'Failed' or boolean")
            return "Passed"

    @staticmethod
    def convert_adapters(adapter_list):
        """
        Convert a list of adapter items to a string with the format:
        "defaults item1 item2 ...".

        :param list adapter_list: List of adapter items.
        :return: Formatted string.
        :rtype: str
        """
        if not adapter_list:
            return ""
        if isinstance(adapter_list, list):
            return ' --adapter-list="defaults ' + ' '.join(adapter_list) + '"'
        elif isinstance(adapter_list, str):
            # In case a string is passed, return it as is
            return f' --adapter-list="{adapter_list}"'
        else:
            logging.debug(f"Invalid adapter_list type: {type(adapter_list)}")
            return ""

    @staticmethod
    def set_default_common_templates_path():
        import taf.ul.marvin
        library_dir = os.path.dirname(taf.ul.marvin.__file__)
        if not library_dir:
            raise ValueError("Library directory not found.")
        return os.path.join(library_dir, 'Common_templates')

    def retrieve_result_from_analysis_response(self, api_link, timeout=20, test_case=False):
        for attempt in range(timeout):
            logging.debug(f"Waiting 1min before checking analysis. {timeout - (attempt + 1)}min left to timeout")
            sleep(60)

            result = self._process_analysis_attempt(api_link, test_case)
            if result is not None:
                return result

        logging.error(f"Analysis result for test run was not available after {timeout}min")
        return None

    def _process_analysis_attempt(self, api_link, test_case):
        """Process a single analysis attempt and return result or None to continue"""
        try:
            data = self.fetch_analysis_data(api_link)
            if data is False:  # Error in fetching data
                return False
            logging.debug(f"Data from {api_link}: {data}")
            match = self._parse_result_from_analysis_json(data, test_case)
            return match
        except Exception as e:
            return self._handle_analysis_exception(e)

    @staticmethod
    def fetch_analysis_data(api_link, data=None):
        try:
            if data:
                response = requests.post(api_link, json=data, verify=False)
            else:
                response = requests.get(api_link, verify=False)
            if response.status_code not in [200, 201]:
                logging.debug(f"Unexpected response from {api_link}(status {response.status_code})")
                return False
            return response.json()
        except (ValueError, requests.RequestException) as e:
            logging.error(f"Error fetching data from {api_link}: {e}")
            return False

    @staticmethod
    def _parse_result_from_analysis_json(data_dict, test_case):
        verdict = data_dict.get("verdict") if not test_case else data_dict.get("test_case").get("verdict")
        if verdict == "Passed":
            logging.debug("Analysis passed all targets!")
            return True
        elif verdict == "Failed":
            logging.debug("Analysis failed one or more targets!")
            return False
        else:
            return None

    @staticmethod
    def _handle_analysis_exception(e):
        logging.error(f"Unexpected exception during analysis: {e}")
        return False

    @staticmethod
    def _retry_operation(operation, max_retries, retry_delay, operation_name):
        """Generic retry helper for operations that may fail."""
        for attempt in range(max_retries):
            try:
                return operation()
            except Exception as e:
                if attempt == max_retries - 1:
                    raise
                logging.debug(
                    f"{operation_name} failed (Attempt {attempt + 1}/{max_retries}): "
                    f"{e}. Retrying in {retry_delay}s..."
                )
                sleep(retry_delay)

    def _connect_ssh_and_sftp(self, server, port, username, password, max_retries=5, retry_delay=45):
        """Establish SSH connection and open SFTP session with retries."""
        ssh_client = paramiko.SSHClient()
        ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())

        def connect():
            logging.debug(f"Connecting to SSH server {server}:{port}...")
            ssh_client.connect(server, port=port, username=username, password=password)
            logging.debug("SSH connection established.")
            logging.debug("Opening SFTP session...")
            sftp = ssh_client.open_sftp()
            logging.debug("SFTP session opened.")
            return ssh_client, sftp

        ssh_client, sftp = self._retry_operation(
            connect, max_retries, retry_delay, "SSH/SFTP connection"
        )
        return ssh_client, sftp

    @staticmethod
    def _ensure_remote_directory_exists(sftp, remote_path):
        """Ensure remote directory exists, create if it doesn't."""
        try:
            sftp.stat(remote_path)
        except FileNotFoundError:
            logging.debug(f"Creating remote directory: {remote_path}")
            sftp.mkdir(remote_path)

    def _upload_file_with_retries(self, sftp, local_path, remote_path, timeout=300, max_retries=3, retry_delay=10):
        """Upload a single file with timeout and retry logic."""
        def upload():
            logging.debug(f"Uploading {os.path.basename(local_path)}...")
            with TimeoutHandler(timeout):
                sftp.put(local_path, remote_path)
            logging.debug(f"Successfully uploaded {os.path.basename(local_path)}")

        self._retry_operation(
            upload, max_retries, retry_delay, f"File upload ({os.path.basename(local_path)})"
        )

    def _upload_all_files(self, sftp, files, remote_path):
        """Upload all files to the remote path."""
        for file_path in files:
            remote_file_path = os.path.join(remote_path, os.path.basename(file_path))
            self._upload_file_with_retries(sftp, file_path, remote_file_path)

    def upload_files_to_analysis_server(self, files,
                                        analysis_name,
                                        analysis_server="100.68.193.200",
                                        analysis_server_port=22,
                                        analysis_server_user="fioucdsusr",
                                        analysis_server_password="!PETlintula1"):
        """
        Upload files to the analysis server.
        """
        timestamp = datetime.now().strftime("%Y_%m_%d_%H_%M")
        analysis_name = f"{analysis_name}_{timestamp}"
        remote_path = f"c:\\TTI_traces\\{analysis_name}"
